-- Run this in the Supabase SQL Editor (Project -> SQL Editor -> New query)
-- Creates a standalone table for the legacy mock product/zone data that
-- previously lived only in lib/db.ts (never persisted to Supabase).
-- Distinct from ledlum_products/ledlum_product_zone, which hold the real,
-- normalized product catalog.

create table public.ledlum_zone_products (
  id          bigint generated always as identity primary key,
  codes       text not null,
  category    text not null,
  image_link  text not null,
  source      text not null default 'internal',
  zone        text not null,        -- zone slug, matches ledlum_zone.slug
  created_at  timestamptz not null default now()
);

create index idx_zone_products_zone on public.ledlum_zone_products(zone);


alter table public.ledlum_zone_products enable row level security;
-- No policies added: matches ledlum_zone/ledlum_products, accessed only
-- server-side via the Supabase service-role key, which bypasses RLS.
